//! Comparison with xtb 6.7.1: solvation energy components computed from
//! xtb's converged charges and geometry (tests/data/*.ref, generated by
//! scripts/xtb_reference.py) against the values printed by xtb (12 decimals).

mod common;

use common::{parse, ref_files};

/// xtb prints 12 decimals: a correct value is within 0.5e-12 of the printed
/// one, plus a little for the floating-point noise of the sums.
const TOL: f64 = 0.6e-12;

#[test]
fn components_match_xtb() {
    let files = ref_files();
    assert!(!files.is_empty(), "no reference data");
    let mut worst = [0.0f64; 5];
    let mut failures = Vec::new();
    println!(
        "{:<40} {:>5} {:>10} {:>10} {:>10} {:>10} {:>10}",
        "case", "nat", "dGsolv", "dGelec", "dGsasa", "dGhb", "dGshift"
    );
    for path in &files {
        let c = parse(path);
        let solv = common::model(&c);
        let cache = solv.update(&c.positions);
        let e = solv.energy_parts(&cache, &c.charges);
        let r = c.reference;
        let d = [e.gsolv - r.gsolv, e.gelec - r.gelec, e.gsasa - r.gsasa, e.ghb - r.ghb, e.gshift - r.gshift];
        println!(
            "{:<40} {:>5} {:>10.2e} {:>10.2e} {:>10.2e} {:>10.2e} {:>10.2e}",
            c.name,
            c.numbers.len(),
            d[0],
            d[1],
            d[2],
            d[3],
            d[4]
        );
        for k in 0..5 {
            worst[k] = worst[k].max(d[k].abs());
        }
        if d.iter().any(|x| x.abs() > TOL) {
            failures.push(c.name.clone());
        }

        // atom-resolved energies add up to the same total
        let mut atomic = vec![0.0; c.numbers.len()];
        solv.fixed_energy(&cache, &mut atomic, None);
        solv.energy(&cache, &c.charges, &mut atomic);
        let tot: f64 = atomic.iter().sum();
        assert!((tot - e.gsolv).abs() < 1e-14, "{}: atomic sum {tot} vs {}", c.name, e.gsolv);
    }
    println!(
        "max |dev| over {} cases: Gsolv {:.2e} Gelec {:.2e} Gsasa {:.2e} Ghb {:.2e} Gshift {:.2e}",
        files.len(),
        worst[0],
        worst[1],
        worst[2],
        worst[3],
        worst[4]
    );
    assert!(failures.is_empty(), "cases outside {TOL:e}: {failures:?}");
}

/// xtb asked for 5810 grid points uses the 5294-point grid (bisectSearch
/// quirk); the zncl4 case above matches xtb only because this is reproduced.
#[test]
fn grid_5810_quirk_is_visible() {
    let mut c = common::load("zncl4_alpb_water_grid5810");
    let a = common::model(&c);
    assert_eq!(a.grid_points(), 5294);
    c.nang = 6000;
    let b = common::model(&c);
    assert_eq!(b.grid_points(), 5810);
    let ea = a.energy_parts(&a.update(&c.positions), &c.charges);
    let eb = b.energy_parts(&b.update(&c.positions), &c.charges);
    println!("Gsasa 5294: {:.15} 5810: {:.15}", ea.gsasa, eb.gsasa);
    assert!((ea.gsasa - c.reference.gsasa).abs() < 0.6e-12);
    assert!((eb.gsasa - c.reference.gsasa).abs() > 1e-11);
}
